import {normalizePhone} from './phone.js';
export async function editApplication(client,eventId,item,isCurrent,onSaved){
 const modal=document.querySelector('#modal'),body=document.querySelector('#modalBody');body.replaceChildren();const heading=document.createElement('h2');heading.textContent='แก้ไขข้อมูลผู้สมัคร';const status=document.createElement('p');status.setAttribute('role','status');status.textContent='กำลังโหลดข้อมูลล่าสุด…';body.append(heading,status);modal.showModal();
 try{const original=await client.operate({action:'contact',eventId,applicationId:item.id});if(!isCurrent()||!modal.open||!heading.isConnected)return;
 const form=document.createElement('form');form.innerHTML='<label>ชื่อ–นามสกุล<input name="displayName" autocomplete="name" maxlength="200" required></label><label>เบอร์โทร<input name="phone" type="tel" inputmode="tel" autocomplete="tel" maxlength="25" required></label><p class="sub">แก้เฉพาะใบสมัครนี้ ระบบเก็บประวัติผู้แก้ไขและข้อมูลก่อน–หลัง</p><button type="submit" class="primary">บันทึกการแก้ไข</button> <button type="button">ยกเลิก</button>';
 form.elements.displayName.value=original.displayName||'';form.elements.phone.value=original.phone||'';status.textContent='';body.insertBefore(form,status);const buttons=form.querySelectorAll('button');buttons[1].onclick=()=>modal.close();
 form.onsubmit=async event=>{event.preventDefault();if(!isCurrent())return;let change;try{change={displayName:form.elements.displayName.value.trim(),phone:normalizePhone(form.elements.phone.value)}}catch(error){status.textContent=error.message;return}buttons.forEach(b=>b.disabled=true);status.textContent='กำลังบันทึก…';try{await client.operate({action:'editApplication',eventId,applicationId:item.id,change,expected:{displayName:original.displayName||'',phone:original.phone||''}});if(!isCurrent())return;onSaved(change);if(heading.isConnected)modal.close()}catch(error){if(heading.isConnected)status.textContent=error.message||'บันทึกไม่ได้ กรุณาลองใหม่'}finally{buttons.forEach(b=>b.disabled=false)}};
 }catch(error){if(heading.isConnected)status.textContent=error.message||'โหลดข้อมูลไม่ได้'}
}
